const originalOpponentPlayers=opponentPlayers;opponentPlayers=function(){const delta=(activeOpponent().strength-70)*.65;return originalOpponentPlayers().map(p=>{for(const key of['tec','pas','fin','tak','pos','spd','sta'])p[key]=clamp(p[key]+delta,20,95);return p})};const originalStart=start;start=function(){if(!activeSave||running||activeSave.currentRound>=10)return;saveCurrent();menuButton.disabled=true;originalStart();const opponent=activeOpponent();$('#subtitle').textContent=`Spieltag ${activeSave.currentRound+1} · ${activeSave.club} gegen ${opponent.name}`;$$('.scoreboard span')[0].textContent=activeSave.club;$$('.scoreboard span')[1].textContent=opponent.name};$('#start').onclick=()=>start();const originalNote=note;note=function(text,kind){originalNote(text.replaceAll('FC Viertel',activeSave?.club||'FC Viertel').replaceAll('SC Hafen',activeSave?activeOpponent().name:'SC Hafen'),kind)};const originalOverlay=showOverlay;showOverlay=function(title,copy,...args){originalOverlay(title,copy.replaceAll('FC Viertel',activeSave?.club||'FC Viertel').replaceAll('SC Hafen',activeSave?activeOpponent().name:'SC Hafen'),...args)};
